document.addEventListener("DOMContentLoaded",()=>{const n=document.getElementById("enabled-checkbox"),e=document.getElementById("confidence-slider"),t=document.getElementById("confidence-value");chrome.storage.sync.get({isEnabled:!0,confidenceThreshold:.8},c=>{n.checked=c.isEnabled,e.value=c.confidenceThreshold,t.textContent=c.confidenceThreshold}),n.addEventListener("change",()=>{chrome.storage.sync.set({isEnabled:n.checked})}),e.addEventListener("input",()=>{t.textContent=e.value}),e.addEventListener("change",()=>{chrome.storage.sync.set({confidenceThreshold:parseFloat(e.value)})})});
